      },
    );
    ctx.entities.add("health-pickup", pickup);

    const registerEnemy = (position: Vector3): Enemy => {
      const id = `enemy.${enemyIndex++}`;
      const enemy = new Enemy(ctx, materials, position, {
        onFire: createEnemyProjectile,
      });
      enemies.push({ id, value: enemy });
      enemyMap.set(enemy.body.body.id, enemy);
      ctx.entities.add(id, enemy);
      enemy.startDetection(ctx, player.body.body.id);
