1	import type { ICtx, ScheduleHandle } from "@threenative/core";
2	import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
3	import { type Group, Vector3 } from "three";
4	import { directSpaceState } from "../physics.js";
5	import { createEnemyVisual } from "../render/shapes.js";
6	import type { GameState } from "../state.js";
7	import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";
8	
9	type GameCtx = ICtx<GameState, IPhysicsContext>;
10	
11	const MOVE_SPEED = 2.5;
12	const CHASE_SPEED = 3.8;
13	const DETECTION_RADIUS = 8;
14	const PATROL_POINTS = [
15	  new Vector3(-6, 0.85, -8),
16	  new Vector3(6, 0.85, -8),
17	  new Vector3(6, 0.85, 2),
18	  new Vector3(-6, 0.85, 2),
19	];
20	
21	export class Enemy {
22	  readonly mesh: Group;
23	  readonly body: CharacterBody3D;
24	  readonly tags = ["hostile", "enemy"];
25	  health = 60;
26	  alive = true;
27	  chasing = false;
28	  #patrolIndex = 0;
29	  #detectionShape = CollisionShape3D.sphere(DETECTION_RADIUS);
30	  #scanHandle: ScheduleHandle | undefined;
31	  #onFire: (origin: Vector3) => void;
32	  #fireTimer = 0;
33	
34	  constructor(
35	    ctx: GameCtx,
36	    materials: Parameters<typeof createEnemyVisual>[0],
37	    position: Vector3,
38	    options: { readonly onFire?: (origin: Vector3) => void } = {},
39	  ) {
40	    this.#onFire = options.onFire ?? (() => undefined);
41	    this.mesh = createEnemyVisual(materials);
42	    this.mesh.position.copy(position);
43	    ctx.add(this.mesh);
44	    this.body = new CharacterBody3D({
45	      collisionLayer: HOSTILE_LAYER,
46	      collisionMask: WORLD_LAYER | PLAYER_LAYER,
47	      autostep: { maxHeight: 0.25, minWidth: 0.18 },
48	      object: this.mesh,
49	      physics: ctx.physics,
50	      shape: CollisionShape3D.capsule(0.4, 0.38),
51	    });
52	  }
53	
54	  startDetection(ctx: GameCtx, playerBodyId: number): void {
55	    const scan = (): void => {
56	      if (!this.alive) return;
57	      const hits = directSpaceState(ctx.physics).intersectShape({
58	        collisionMask: PLAYER_LAYER,
59	        maxResults: 1,
60	        position: this.mesh.position,
61	        shape: this.#detectionShape,
62	      });
63	      this.chasing = hits.some((hit) => hit.body.id === playerBodyId);
64	      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
65	    };
66	    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
