import type { ICtx, ScheduleHandle } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const MOVE_SPEED = 2.5;
const CHASE_SPEED = 3.8;
const DETECTION_RADIUS = 8;
const PATROL_POINTS = [
  new Vector3(-6, 0.85, -8),
  new Vector3(6, 0.85, -8),
  new Vector3(6, 0.85, 2),
  new Vector3(-6, 0.85, 2),
];

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health = 60;
  alive = true;
  chasing = false;
  #patrolIndex = 0;
  #detectionShape = CollisionShape3D.sphere(DETECTION_RADIUS);
  #scanHandle: ScheduleHandle | undefined;
  #onFire: (origin: Vector3) => void;
  #fireTimer = 0;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    options: { readonly onFire?: (origin: Vector3) => void } = {},
  ) {
    this.#onFire = options.onFire ?? (() => undefined);
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);
    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.38),
    });
  }

  startDetection(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 1,
        position: this.mesh.position,
        shape: this.#detectionShape,
      });
      this.chasing = hits.some((hit) => hit.body.id === playerBodyId);
      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
    };
    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
  }

  update(ctx: GameCtx, dt: number, playerPos: Vector3): void {
    if (!this.alive) return;

    const targetPos = this.chasing ? playerPos : PATROL_POINTS[this.#patrolIndex];
    const direction = targetPos.clone().sub(this.mesh.position);
    const distanceSq = direction.lengthSq();

    if (!this.chasing && distanceSq < 0.5 * 0.5) {
      this.#patrolIndex = (this.#patrolIndex + 1) % PATROL_POINTS.length;
    }

    direction.normalize();
    const speed = this.chasing ? CHASE_SPEED : MOVE_SPEED;
    this.body.velocity.x = direction.x * speed;
    this.body.velocity.z = direction.z * speed;
    this.body.moveAndSlide(dt);

    if (!this.chasing) return;
    this.#fireTimer -= dt;
    if (this.#fireTimer > 0) return;
    this.#fireTimer = 4;
    this.#onFire(this.mesh.position.clone().add(new Vector3(0.35, 0.65, 0)));
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      chasing: this.chasing,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

